  {"id":569,"category":"السيرة","difficulty":"صعب","type":"mcq","question":"كم كان عدد المبايعين من الأنصار في بيعة العقبة الأولى؟","options":["سبعون رجلاً","أربعون رجلاً","عشرون رجلاً","اثنا عشر رجلاً"],"correct":3,"source":"سيرة ابن هشام؛ البداية والنهاية لابن كثير","explanation":"بايع اثنا عشر رجلاً من الأنصار في بيعة العقبة الأولى، وأرسل النبي ﷺ معهم مصعب بن عمير."},
  {"id":570,"category":"السيرة","difficulty":"صعب","type":"mcq","question":"من الصحابي الأنصاري الذي آخى النبي ﷺ بينه وبين عبد الرحمن بن عوف عند قدومه المدينة؟","options":["سعد بن الربيع","سعد بن معاذ","أبو أيوب الأنصاري","أسعد بن زرارة"],"correct":0,"source":"صحيح البخاري، كتاب البيوع؛ سيرة ابن هشام","explanation":"آخى النبي ﷺ بين عبد الرحمن بن عوف وسعد بن الربيع رضي الله عنهما."},
  {"id":571,"category":"السيرة","difficulty":"صعب","type":"mcq","question":"من الصحابي الذي استضاف النبي ﷺ في داره بالمدينة المنورة حتى بُني المسجد النبوي وحجراته؟","options":["سعد بن عبادة","أبو أيوب الأنصاري","البراء بن معرور","سعد بن معاذ"],"correct":1,"source":"صحيح البخاري، كتاب مناقب الأنصار؛ سيرة ابن هشام","explanation":"نزل النبي ﷺ في بيت أبي أيوب الأنصاري رضي الله عنه عند قدومه المدينة."},
  {"id":572,"category":"السيرة","difficulty":"صعب","type":"mcq","question":"من رأس المنافقين الذي انسحب بثلث الجيش قبيل غزوة أُحد؟","options":["أبو عامر الراهب","الأخنس بن شريق","عبد الله بن أُبيّ بن سلول","صفوان بن أمية"],"correct":2,"source":"سيرة ابن هشام؛ صحيح البخاري، كتاب المغازي","explanation":"انخذل عبد الله بن أُبيّ بن سلول بنحو ثلاث مئة مقاتل في الطريق إلى أُحد."},
  {"id":573,"category":"السيرة","difficulty":"صعب","type":"mcq","question":"من الدليل الخبير بالطرق الذي استأجره النبي ﷺ وأبو بكر الصديق ليدلّهما في طريق الهجرة؟","options":["عامر بن فهيرة","سراقة بن مالك","أبو بكر بن أبي قحافة","عبد الله بن أُرَيْقِط"],"correct":3,"source":"صحيح البخاري، كتاب مناقب الأنصار؛ سيرة ابن هشام","explanation":"استأجر النبي ﷺ وأبو بكر عبد الله بن أُريقط وكان خبيراً بطرق الصحراء وأميناً على السر."},
  {"id":574,"category":"السيرة","difficulty":"صعب","type":"mcq","question":"ما اسم الحلف الجاهلي الذي شهده النبي ﷺ لنصرة المظلوم وقال عنه: «لو دُعيت به في الإسلام لأجبت»؟","options":["حلف الفضول","حلف المطيبين","حلف الأحابيش","حلف الخندق"],"correct":0,"source":"سيرة ابن هشام؛ مسند الإمام أحمد","explanation":"حضر النبي ﷺ في شبابه حلف الفضول في دار عبد الله بن جدعان لنصرة المظلوم بمكة."},
  {"id":575,"category":"الفقه","difficulty":"سهل","type":"mcq","question":"كم عدد فروض الوضوء الأساسية المنصوص عليها في آية سورة المائدة؟","options":["فَرْضان","أربعة فروض","سبعة فروض","عشرة فروض"],"correct":1,"source":"سورة المائدة، الآية 6","explanation":"فروض الوضوء الأربعة في الآية هي: غسل الوجه، واليدين إلى المرفقين، ومسح الرأس، وغسل الرجلين إلى الكعبين."},
  {"id":576,"category":"الفقه","difficulty":"سهل","type":"mcq","question":"في أي الصلوات المفروضة يُسَرّ بالقراءة في جميع ركعاتها؟","options":["الفجر والمغرب","المغرب والعشاء","الظهر والعصر","الجمعة والفجر"],"correct":2,"source":"المغني لابن قدامة؛ صفة صلاة النبي","explanation":"صلاتا الظهر والعصر نهاريتان يُسَرّ فيهما بالقراءة في جميع الركعات."},
  {"id":577,"category":"الفقه","difficulty":"سهل","type":"mcq","question":"ما الصدقة المفروضة في ختام شهر رمضان قبل صلاة العيد؟","options":["زكاة الركاز","زكاة الأنعام","الأضحية","زكاة الفطر"],"correct":3,"source":"صحيح البخاري، حديث 1503؛ صحيح مسلم، حديث 984","explanation":"فرض رسول الله ﷺ زكاة الفطر طُهرة للصائم من اللغو والرفث وطُعمة للمساكين."},
  {"id":578,"category":"الفقه","difficulty":"سهل","type":"mcq","question":"ما الركن الأعظم من أركان الحج الذي قال عنه النبي ﷺ: «الحج عرفة»؟","options":["الوقوف بعرفة","طواف القدوم","رمي الجمرات","المبيت بمنى"],"correct":0,"source":"سنن الترمذي، كتاب الحج؛ سنن أبي داود، كتاب المناسك","explanation":"الوقوف بعرفة هو ركن الحج الأعظم ومن فاته فقد فاته الحج."},
  {"id":579,"category":"الفقه","difficulty":"سهل","type":"mcq","question":"متى يدخل وقت صلاة المغرب؟","options":["عند اصفرار الشمس","بغروب قرص الشمس كاملاً","بعد زوال الشمس","عند طلوع الفجر الصادق"],"correct":1,"source":"صحيح مسلم، كتاب المساجد ومواضع الصلاة","explanation":"يدخل وقت صلاة المغرب إذا غاب جميع قرص الشمس في الأفق."},
  {"id":580,"category":"الفقه","difficulty":"سهل","type":"mcq","question":"ما حكم من أكل أو شرب ناسياً في نهار رمضان؟","options":["يفسد صومه وعليه القضاء","عليه الكفارة المغلظة","صيامه صحيح ويُتمّ صومه","يفطر بقية اليوم"],"correct":2,"source":"صحيح البخاري، حديث 1933؛ صحيح مسلم، حديث 1155","explanation":"قال ﷺ: «من نسي وهو صائم فأكل أو شرب فليتم صومه، فإنما أطعمه الله وسقاه»."},
  {"id":581,"category":"الفقه","difficulty":"سهل","type":"mcq","question":"أي من الصلوات التالية يُشرع أداؤها بلا أذان ولا إقامة؟","options":["صلاة الفجر","صلاة الجمعة","صلاة المغرب","صلاة العيدين"],"correct":3,"source":"صحيح مسلم، كتاب صلاة العيدين؛ المغني لابن قدامة","explanation":"ثبت في السنة أن صلاتي عيد الفطر وعيد الأضحى تؤدّيان من غير أذان ولا إقامة."},
  {"id":582,"category":"الفقه","difficulty":"متوسط","type":"mcq","question":"من أين يُحرم أهل مكة إذا أرادوا الحج منها؟","options":["من مكة نفسها (من منازلهم)","من ذي الحليفة","من الجحفة","من قرن المنازل"],"correct":0,"source":"صحيح البخاري، حديث 1524","explanation":"المقيمون في مكة يحرمون بالحج من مكة نفسها، أما العمرة فيخرجون إلى الحل كالتنعيم."},
  {"id":583,"category":"الفقه","difficulty":"متوسط","type":"mcq","question":"ما الموضع الذي يبدأ منه الطواف حول الكعبة المشرفة وينتهي إليه كل شوط؟","options":["مقام إبراهيم","الحجر الأسود","الركن اليماني","حجر إسماعيل"],"correct":1,"source":"صحيح البخاري، كتاب الحج","explanation":"يبدأ الطائف كل شوط محاذياً للحجر الأسود ويجعل الكعبة عن يساره."},
  {"id":584,"category":"الفقه","difficulty":"متوسط","type":"mcq","question":"ما نوع الحج الذي يُحرم فيه الحاج بالعمرة في أشهر الحج ويتحلل منها ثم يحرم بالحج في العام نفسه؟","options":["الإفراد","القِران","التَّمتُّع","الاعتكاف"],"correct":2,"source":"صحيح البخاري، كتاب الحج؛ المغني لابن قدامة","explanation":"حج التمتع هو الإحرام بالعمرة أولاً في أشهر الحج والتحلل منها، ثم الإحرام بالحج يوم التروية."},
  {"id":585,"category":"الفقه","difficulty":"متوسط","type":"mcq","question":"ما مقدار الواجب في زكاة الرِّكاز (الكنز المدفون من الجاهلية)؟","options":["العُشر (10%)","نصف العُشر (5%)","ربع العُشر (2.5%)","الخُمس (20%)"],"correct":3,"source":"صحيح البخاري، حديث 1499؛ صحيح مسلم، حديث 1710","explanation":"ثبت في الصحيحين قول النبي ﷺ: «وفي الركاز الخُمس»."},
  {"id":586,"category":"الفقه","difficulty":"متوسط","type":"mcq","question":"أي الصلوات الخمس ثبت في صحيح مسلم أنها «الصلاة الوسطى» المأمور بالمحافظة عليها؟","options":["صلاة العصر","صلاة الظهر","صلاة الفجر","صلاة العشاء"],"correct":0,"source":"صحيح مسلم، كتاب المساجد؛ سورة البقرة، الآية 238","explanation":"روى مسلم عن النبي ﷺ يوم الأحزاب أنه سمّى صلاة العصر بالصلاة الوسطى."},
  {"id":587,"category":"الفقه","difficulty":"متوسط","type":"mcq","question":"ما الحكم الشرعي لصلاة الجنازة على الميت المسلم؟","options":["فرض عين على كل مسلم","فرض كفاية","سنة مهجورة","مباحة اختيارية"],"correct":1,"source":"المغني لابن قدامة؛ الفقه المنهجي","explanation":"صلاة الجنازة فرض كفاية، إذا قام بها بعض المسلمين سقط الإثم عن الباقين."},
  {"id":588,"category":"الفقه","difficulty":"متوسط","type":"mcq","question":"كم عدد «أيام التشريق» التي تلي يوم عيد الأضحى مباشرة؟","options":["يومان فقط","أربعة أيام","ثلاثة أيام (11 و12 و13 ذي الحجة)","خمسة أيام"],"correct":2,"source":"صحيح البخاري، كتاب الصوم؛ سورة البقرة، الآية 203","explanation":"أيام التشريق ثلاثة أيام بعد يوم النحر، وهي أيام أكل وشرب وذكر الله."},
  {"id":589,"category":"الفقه","difficulty":"صعب","type":"mcq","question":"ما كفارة اليمين المنعقدة كما وردت مرتبة في سورة المائدة؟","options":["صيام شهرين متتابعين ابتداءً","إطعام ستين مسكيناً","إخراج ربع العشر من المال","إطعام عشرة مساكين أو كسوتهم أو تحرير رقبة، فإن لم يجد فصيام ثلاثة أيام"],"correct":3,"source":"سورة المائدة، الآية 89","explanation":"بيّنت الآية 89 من سورة المائدة خصال التخيير الثلاث أولاً ثم الصيام عند العجز."},
  {"id":590,"category":"الفقه","difficulty":"صعب","type":"mcq","question":"أي أنواع الطواف يُعدّ ركناً من أركان الحج لا يصح الحج بدونه عند جمهور الفقهاء؟","options":["طواف الإفاضة (الزيارة)","طواف القدوم","طواف الوداع","طواف التطوع"],"correct":0,"source":"سورة الحج، الآية 29؛ المغني لابن قدامة","explanation":"طواف الإفاضة هو الطواف المأمور به في قوله تعالى: «وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ»."},
  {"id":591,"category":"الفقه","difficulty":"صعب","type":"mcq","question":"ما حكم تعمّد صيام «يوم الشك» بنية الاحتياط لرمضان عند جمهور العلماء؟","options":["واجب على كل بالغ","منهيّ عنه","سنة مؤكدة","مطلوب في السفر فقط"],"correct":1,"source":"سنن أبي داود، كتاب الصوم؛ سنن الترمذي، باب ما جاء في كراهية صوم يوم الشك","explanation":"نُقل عن عمار بن ياسر رضي الله عنه: «من صام اليوم الذي يُشك فيه فقد عصى أبا القاسم ﷺ»."},
  {"id":592,"category":"الفقه","difficulty":"صعب","type":"mcq","question":"أي الوارثَين يرث نصف التركة عند انفراده وعدم وجود عاصب أو فرع وارث؟","options":["الأب مع وجود الابن","الأم مع وجود الإخوة","البنت الواحدة، والزوج إن لم يكن للزوجة فرع وارث","الجد مع وجود الأب"],"correct":2,"source":"سورة النساء، الآيات 11–12","explanation":"ترث البنت الواحدة المنفردة النصف، ويرث الزوج النصف إن لم تترك الزوجة فرعاً وارثاً."},
  {"id":593,"category":"الفقه","difficulty":"صعب","type":"mcq","question":"في كم شوطٍ من طواف القدوم يُسَنّ للرجل «الرَّمَل» (الإسراع في المشي مع تقارب الخطى)؟","options":["الأشواط السبعة كلها","الشوط الأول فقط","الأشواط الأربعة الأخيرة","الأشواط الثلاثة الأولى"],"correct":3,"source":"صحيح البخاري، كتاب الحج؛ صحيح مسلم، كتاب الحج","explanation":"يُسن الرَّمل في الأشواط الثلاثة الأولى من طواف القدوم والمشي في الأربعة الباقية."},
  {"id":594,"category":"الفقه","difficulty":"صعب","type":"mcq","question":"ما حكم بيع «الغَرَر» (البيع المجهول العاقبة أو الصفة) في الفقه الإسلامي؟","options":["محرّم ومنهيّ عنه","مكروه تنزيهاً فقط","مستحب في التجارة","واجب عند الضرورة"],"correct":0,"source":"صحيح مسلم، حديث 1513","explanation":"ثبت في صحيح مسلم عن أبي هريرة أن النبي ﷺ نهى عن بيع الحصاة وعن بيع الغرر."},
  {"id":595,"category":"الحديث","difficulty":"سهل","type":"mcq","question":"أكمل الحديث الصحيح: «المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف، وفي كلٍّ...»","options":["أجر","خير","نور","فضل"],"correct":1,"source":"صحيح مسلم، حديث 2664","explanation":"هذا الحديث يحثّ على القوة في الإيمان والعمل مع إثبات أصل الخير في كل مؤمن."},
  {"id":596,"category":"الحديث","difficulty":"سهل","type":"mcq","question":"أكمل الحديث المتفق عليه: «اتَّقوا النار ولو بـ...»","options":["كلمة عابرة","خطوة قصيرة","شِقِّ تمرة","درهم واحد"],"correct":2,"source":"صحيح البخاري، حديث 1417؛ صحيح مسلم، حديث 1016","explanation":"فيه بيان فضل الصدقة ولو كانت يسيرة كشق تمرة تقي صاحبها من النار."},
  {"id":597,"category":"الحديث","difficulty":"سهل","type":"mcq","question":"أكمل الحديث المتفق عليه: «كُلُّكم راعٍ وكُلُّكم مسؤول عن...»","options":["تجارته","ماله","جيرانه","رَعِيَّته"],"correct":3,"source":"صحيح البخاري، حديث 893","explanation":"يرسخ الحديث مبدأ المسؤولية الفردية لكل إنسان عمن استُرعي عليه."},
  {"id":598,"category":"الحديث","difficulty":"سهل","type":"mcq","question":"أكمل الحديث المتفق عليه: «يَسِّروا ولا تُعَسِّروا، وبَشِّروا ولا...»","options":["تُنَفِّروا","تُسرعوا","تُؤَخِّروا","تُحَذِّروا"],"correct":0,"source":"صحيح البخاري، حديث 69","explanation":"يوصي النبي ﷺ بالتيسير والبشارة في الدعوة والتعليم وعدم التنفير."},
  {"id":599,"category":"الحديث","difficulty":"سهل","type":"mcq","question":"أكمل الحديث الثابت في الصحيحين: «الظُّلْمُ ظُلُماتٌ...»","options":["في الدنيا فقط","يوم القيامة","في القبر وحده","عند السفر"],"correct":1,"source":"صحيح البخاري، حديث 2447؛ صحيح مسلم، كتاب البر والصلة","explanation":"الظلم يكون ظلمات شديدة على صاحبه يوم القيامة، ولذا حُرّم بجميع أنواعه."},
  {"id":600,"category":"الحديث","difficulty":"سهل","type":"mcq","question":"أكمل الحديث الذي رواه مسلم: «من نفَّس عن مؤمن كُربةً من كُرَب الدنيا نفَّس الله عنه كربةً من...»","options":["هموم الدنيا فقط","ساعات الليل","كُرَب يوم القيامة","شدائد السفر"],"correct":2,"source":"صحيح مسلم، حديث 2699","explanation":"الجزاء من جنس العمل؛ من يسر على مؤمن كربة دنيوية فرّج الله عنه كربة يوم القيامة."},
  {"id":601,"category":"الحديث","difficulty":"سهل","type":"mcq","question":"أكمل الحديث المتفق عليه: «الحَيَاءُ لا يأتي إلا بـ...»","options":["حزن","تعب","خوف","خير"],"correct":3,"source":"صحيح البخاري، حديث 6117؛ صحيح مسلم، حديث 37","explanation":"الحياء خلق محمود يبعث على فعل الحسن وترك القبيح ولا يأتي إلا بخير."},
  {"id":602,"category":"الحديث","difficulty":"متوسط","type":"mcq","question":"أكمل الحديث الذي رواه مسلم: «ما نقصت صدقةٌ من مال، وما زاد الله عبداً بعفوٍ إلا...»","options":["عِزّاً","مالاً","نَسَباً","عُمراً"],"correct":0,"source":"صحيح مسلم، حديث 2588","explanation":"يؤكد الحديث أن الصدقة لا تُنقص المال بركةً وأثراً، وأن العفو يرفع قدر صاحبه ويعزّه."},
  {"id":603,"category":"الحديث","difficulty":"متوسط","type":"mcq","question":"أكمل الحديث المتفق عليه: «ليس الشديدُ بالصُّرَعة، إنما الشديد الذي يملك نفسه عند...»","options":["الجوع","الغضب","السفر","النوم"],"correct":1,"source":"صحيح البخاري، حديث 6114؛ صحيح مسلم، حديث 2609","explanation":"القوة الحقيقية هي ضبط النفس وكظم الغيظ عند الغضب."},
  {"id":604,"category":"الحديث","difficulty":"متوسط","type":"mcq","question":"أكمل الحديث المتفق عليه: «مَثَلُ المؤمنين في توادِّهم وتراحمهم وتعاطفهم مثل...»","options":["البحر الواسع","الشجرة اليابسة","الجسد الواحد","الجبل الراسخ"],"correct":2,"source":"صحيح البخاري، حديث 6011؛ صحيح مسلم، حديث 2586","explanation":"شبه النبي ﷺ تلاحم المؤمنين بالجسد الواحد إذا اشتكى منه عضو تداعى له سائر الجسد."},
  {"id":605,"category":"الحديث","difficulty":"متوسط","type":"mcq","question":"أكمل الحديث المتفق عليه: «ألا وإنَّ في الجسد مُضغةً إذا صلَحَتْ صلح الجسد كله... ألا وهي...»","options":["اللسان","العقل","اليد","القلب"],"correct":3,"source":"صحيح البخاري، حديث 52؛ صحيح مسلم، حديث 1599","explanation":"صلاح القلب هو أساس صلاح الجوارح والأعمال كلها."},
  {"id":606,"category":"الحديث","difficulty":"متوسط","type":"mcq","question":"أكمل الحديث المتفق عليه: «لا تباغضوا، ولا تحاسدوا، ولا تدابروا، وكونوا عباد الله...»","options":["إخواناً","متنافسين","متفرقين","متحذرين"],"correct":0,"source":"صحيح البخاري، حديث 6065؛ صحيح مسلم، حديث 2559","explanation":"ينهى الحديث عن التباغض والتحاسد والهجر ويأمر بالأخوة الإيمانية."},
  {"id":607,"category":"الحديث","difficulty":"متوسط","type":"mcq","question":"أكمل الحديث المتفق عليه: «ما يُصيبُ المسلمَ من نَصَبٍ ولا وَصَبٍ ولا هَمٍّ ولا حَزَنٍ... إلا كفَّر الله بها من...»","options":["ديونه","خطاياه","أمواله","أسفاره"],"correct":1,"source":"صحيح البخاري، حديث 5641؛ صحيح مسلم، حديث 2573","explanation":"الابتلاءات والآلام التي تصيب المسلم مع الصبر والاحتساب تكون كفارة لذنوبه."},
  {"id":608,"category":"الحديث","difficulty":"متوسط","type":"mcq","question":"أكمل الحديث الذي رواه البخاري: «مَن لَمْ يَدَعْ قولَ الزُّور والعملَ به فليس لله حاجة في أن يَدَعَ...»","options":["نومَه وراحتَه","تجارتَه وعملَه","طعامَه وشرابَه","بيتَه وأهلَه"],"correct":2,"source":"صحيح البخاري، حديث 1903","explanation":"حكمة الصيام تحقيق التقوى واجتناب المحرمات، لا مجرد الإمساك عن الطعام والشراب."},
  {"id":609,"category":"الحديث","difficulty":"صعب","type":"mcq","question":"من الإمام الذي جمع كتاب «الأربعين النووية» المشهور في جوامع الكلم النبوية؟","options":["الإمام ابن حجر العسقلاني","الإمام السيوطي","الإمام ابن رجب الحنبلي","الإمام يحيى بن شرف النووي"],"correct":3,"source":"الأربعون النووية، مقدمة المؤلف","explanation":"صنّفه الإمام محيي الدين يحيى بن شرف النووي رحمه الله في القرن السابع الهجري."},
  {"id":610,"category":"الحديث","difficulty":"صعب","type":"mcq","question":"كم عدد الأحاديث في كتاب «الأربعين النووية» للإمام النووي قبل زيادة ابن رجب؟","options":["42 حديثاً","40 حديثاً بالضبط","50 حديثاً","35 حديثاً"],"correct":0,"source":"الأربعون النووية للإمام النووي، الأحاديث 1–42","explanation":"تحتوي الأربعون النووية في أصلها الذي رتبه الإمام النووي على 42 حديثاً."},
  {"id":611,"category":"الحديث","difficulty":"صعب","type":"mcq","question":"أكمل الحديث القدسي في الصحيحين: «يقول الله تعالى: أنا عند ظنّ عبدي بي، وأنا معه إذا...»","options":["سافر","ذكرني","نام","صمت"],"correct":1,"source":"صحيح البخاري، حديث 7405؛ صحيح مسلم، حديث 2675","explanation":"يحث الحديث القدسي على حسن الظن بالله والإكثار من ذكره سبحانه."},
  {"id":612,"category":"الحديث","difficulty":"صعب","type":"mcq","question":"أكمل الحديث المتفق عليه: «تُنْكَحُ المرأةُ لأربعٍ: لمالها ولحسبها وجمالها ولدينها، فاظفر بذات...»","options":["المال","الحسب","الدِّين","الجمال"],"correct":2,"source":"صحيح البخاري، حديث 5090؛ صحيح مسلم، حديث 1466","explanation":"يرشد النبي ﷺ إلى تقديم صاحبة الدين والخلق عند اختيار الزوجة."},
  {"id":613,"category":"الحديث","difficulty":"صعب","type":"mcq","question":"ما اسم الكتاب الشهير الذي جمع فيه الإمام النووي أحاديث الآداب والرقائق والأخلاق من الصحيحين والسنن؟","options":["بلوغ المرام","عمدة الأحكام","الجامع الصغير","رياض الصالحين"],"correct":3,"source":"رياض الصالحين للإمام النووي","explanation":"كتاب رياض الصالحين من كلام سيد المرسلين للإمام النووي من أشهر كتب الرقائق والأخلاق."},
  {"id":614,"category":"الحديث","difficulty":"صعب","type":"mcq","question":"من مؤلف كتاب «سنن أبي داود» أحد الكتب الستة في الحديث الشريف؟","options":["سليمان بن الأشعث السجستاني","أحمد بن شعيب النسائي","محمد بن عيسى الترمذي","محمد بن يزيد ابن ماجه"],"correct":0,"source":"سير أعلام النبلاء للذهبي؛ مقدمة سنن أبي داود","explanation":"أبو داود هو الإمام الحافظ سليمان بن الأشعث السجستاني (ت 275هـ)."},
  {"id":615,"category":"التاريخ","difficulty":"سهل","type":"mcq","question":"ما المسجد التاريخي الثالث في الفضل الذي تُشدّ إليه الرحال ويقع في بيت المقدس؟","options":["مسجد قباء","المسجد الأقصى","المسجد الأموي","الجامع الأزهر"],"correct":1,"source":"صحيح البخاري، حديث 1189","explanation":"ثبت في الحديث أن الرحال لا تُشد إلا إلى المسجد الحرام والمسجد النبوي والمسجد الأقصى."},
  {"id":616,"category":"التاريخ","difficulty":"سهل","type":"mcq","question":"من الخليفة الراشد الذي دوّن الدواوين واعتمد التقويم الهجري في عهده؟","options":["أبو بكر الصديق","عثمان بن عفان","عمر بن الخطاب","علي بن أبي طالب"],"correct":2,"source":"تاريخ الأمم والملوك للطبري؛ البداية والنهاية لابن كثير","explanation":"أنشأ عمر بن الخطاب رضي الله عنه الدواوين وأرّخ بالهجرة النبوية في السنة السابعة عشرة للهجرة."},
  {"id":617,"category":"التاريخ","difficulty":"سهل","type":"mcq","question":"في عهد أي خليفة راشد أُنشئ أول أسطول بحري إسلامي لفتح قبرص وحماية السواحل؟","options":["أبو بكر الصديق","عمر بن الخطاب","علي بن أبي طالب","عثمان بن عفان"],"correct":3,"source":"تاريخ الطبري؛ البداية والنهاية لابن كثير","explanation":"أذن عثمان بن عفان رضي الله عنه بركوب البحر وبناء الأسطول الإسلامي الأول."},
  {"id":618,"category":"التاريخ","difficulty":"سهل","type":"mcq","question":"ما المدينة التي أسسها عقبة بن نافع في بلاد المغرب العربي لتكون قاعدة للجيش الإسلامي؟","options":["القيروان","فاس","تونس","الرباط"],"correct":0,"source":"الكامل في التاريخ لابن الأثير؛ البداية والنهاية لابن كثير","explanation":"أسس عقبة بن نافع مدينة القيروان نحو سنة 50هـ لتكون مركزاً لنشر الإسلام في إفريقية."},
  {"id":619,"category":"التاريخ","difficulty":"سهل","type":"mcq","question":"من الخليفة الذي سيّر الجيوش الأحد عشر لمواجهة المرتدين ومسيلمة الكذاب بعد وفاة النبي ﷺ؟","options":["عمر بن الخطاب","أبو بكر الصديق","عثمان بن عفان","معاوية بن أبي سفيان"],"correct":1,"source":"تاريخ الطبري؛ البداية والنهاية لابن كثير","explanation":"اتخذ أبو بكر الصديق رضي الله عنه قراراً حازماً بقتال المرتدين وتثبيت أركان الدولة."},
  {"id":620,"category":"التاريخ","difficulty":"سهل","type":"mcq","question":"في أي مدينة مصرية أُسس الجامع الأزهر في القرن الرابع الهجري؟","options":["الإسكندرية","أسوان","القاهرة","دمياط"],"correct":2,"source":"البداية والنهاية لابن كثير؛ الخطط للمقريزي","explanation":"شُرع في بناء الجامع الأزهر في مدينة القاهرة سنة 359هـ."},
  {"id":621,"category":"التاريخ","difficulty":"متوسط","type":"mcq","question":"من قائد المسلمين في معركة اليمامة ضد مسيلمة الكذاب في حروب الردة؟","options":["عمرو بن العاص","أبو عبيدة بن الجراح","عكرمة بن أبي جهل","خالد بن الوليد"],"correct":3,"source":"تاريخ الطبري؛ البداية والنهاية لابن كثير","explanation":"انتصر جيش المسلمين بقيادة خالد بن الوليد رضي الله عنه في موقعة اليمامة سنة 11هـ/12هـ."},
  {"id":622,"category":"التاريخ","difficulty":"متوسط","type":"mcq","question":"من الخليفة الأموي الذي عرّب الدواوين وسكّ أول دينار إسلامي خالص؟","options":["عبد الملك بن مروان","الوليد بن عبد الملك","هشام بن عبد الملك","يزيد بن معاوية"],"correct":0,"source":"تاريخ الطبري؛ البداية والنهاية لابن كثير","explanation":"أمر عبد الملك بن مروان بتعريب الدواوين وسكّ العملة الإسلامية الخالصة."},
  {"id":623,"category":"التاريخ","difficulty":"متوسط","type":"mcq","question":"ما اسم المدينة التي أنشأها عمرو بن العاص في مصر بعد فتحها لتكون عاصمتها الأولى في الإسلام؟","options":["الإسكندرية","الفسطاط","القطائع","العسكر"],"correct":1,"source":"تاريخ الطبري؛ فتوح مصر لابن عبد الحكم","explanation":"اختطّ عمرو بن العاص مدينة الفسطاط وبنى فيها مسجده الجامع سنة 21هـ."},
  {"id":624,"category":"التاريخ","difficulty":"متوسط","type":"mcq","question":"من العالم المسلم صاحب كتاب «المختصر في حساب الجبر والمقابلة» الذي نُسب إليه علم الجبر؟","options":["ابن سينا","جابر بن حيان","محمد بن موسى الخوارزمي","أبو الريحان البيروني"],"correct":2,"source":"تاريخ الحكماء للقفطي؛ الجبر والمقابلة للخوارزمي","explanation":"وضع محمد بن موسى الخوارزمي أسس علم الجبر في بغداد في العصر العباسي."},
  {"id":625,"category":"التاريخ","difficulty":"متوسط","type":"mcq","question":"في أي معركة بحرية كبرى انتصر الأسطول الإسلامي على الأسطول البيزنطي سنة 34هـ في عهد عثمان بن عفان؟","options":["معركة الجمل","معركة نهاوند","معركة ملاذكرد","معركة ذات الصواري"],"correct":3,"source":"تاريخ الطبري؛ الكامل في التاريخ لابن الأثير","explanation":"انتصر المسلمون بقيادة عبد الله بن سعد بن أبي السرح في معركة ذات الصواري سنة 34هـ."},
  {"id":626,"category":"التاريخ","difficulty":"متوسط","type":"mcq","question":"من الصحابي الجليل الذي ولّاه عمر بن الخطاب القيادة العامة لجيوش الشام خلفاً لخالد بن الوليد؟","options":["أبو عبيدة بن الجراح","شرحبيل بن حسنة","يزيد بن أبي سفيان","عمرو بن العاص"],"correct":0,"source":"تاريخ الطبري؛ البداية والنهاية لابن كثير","explanation":"تولّى أبو عبيدة بن الجراح رضي الله عنه قيادة جيوش الشام وفتح دمشق وبيت المقدس."},
  {"id":627,"category":"التاريخ","difficulty":"صعب","type":"mcq","question":"من السلطان السلجوقي الذي انتصر على الإمبراطور البيزنطي رومانوس الرابع في معركة «ملاذكرد» سنة 463هـ؟","options":["طغرل بك","ألب أرسلان","ملكشاه","نور الدين زنكي"],"correct":1,"source":"الكامل في التاريخ لابن الأثير؛ البداية والنهاية لابن كثير","explanation":"حقق السلطان ألب أرسلان نصراً حاسماً في معركة ملاذكرد سنة 463هـ فتح الأناضول للإسلام."},
  {"id":628,"category":"التاريخ","difficulty":"صعب","type":"mcq","question":"من القائد الأموي الذي فتح معظم بلاد ما وراء النهر حتى بلغ تخوم الصين في عهد الوليد بن عبد الملك؟","options":["موسى بن نصير","الحجاج بن يوسف","قتيبة بن مسلم الباهلي","المهلب بن أبي صفرة"],"correct":2,"source":"تاريخ الطبري؛ الكامل في التاريخ لابن الأثير","explanation":"قاد قتيبة بن مسلم الباهلي فتوحات بخارى وسمرقند وبلاد ما وراء النهر."},
  {"id":629,"category":"التاريخ","difficulty":"صعب","type":"mcq","question":"من الخليفة العباسي الذي بنى مدينة «سامراء» ونقل إليها مقر الخلافة سنة 221هـ؟","options":["المأمون","الواثق بالله","المتوكل على الله","المعتصم بالله"],"correct":3,"source":"تاريخ الطبري؛ البداية والنهاية لابن كثير","explanation":"أسس الخليفة المعتصم بالله العباسي مدينة سامراء سنة 221هـ."},
  {"id":630,"category":"التاريخ","difficulty":"صعب","type":"mcq","question":"من الوالي الأموي على إفريقية الذي عبَر إلى الأندلس سنة 93هـ ليكمل فتحها بعد طارق بن زياد؟","options":["موسى بن نُصير","حسان بن النعمان","عبد العزيز بن مروان","عقبة بن نافع"],"correct":0,"source":"الكامل في التاريخ لابن الأثير؛ نفح الطيب للمقري","explanation":"عبر موسى بن نصير بجيشه سنة 93هـ وأتمّ فتح عدة مدن أندلسية كإشبيلية وماردة."},
  {"id":631,"category":"التاريخ","difficulty":"صعب","type":"mcq","question":"من المؤرخ والمحدّث الكبير مؤلف موسوعة «سير أعلام النبلاء» و«تاريخ الإسلام»؟","options":["الحافظ ابن حجر العسقلاني","الإمام شمس الدين الذهبي","الحافظ ابن كثير","الخطيب البغدادي"],"correct":1,"source":"سير أعلام النبلاء للإمام الذهبي","explanation":"ألّف الإمام شمس الدين الذهبي (ت 748هـ) كتابي سير أعلام النبلاء وتاريخ الإسلام."},
  {"id":632,"category":"التاريخ","difficulty":"صعب","type":"mcq","question":"ما المعركة التي وقعت سنة 114هـ (732م) في بلاد الغال (فرنسا) واستشهد فيها القائد عبد الرحمن الغافقي؟","options":["معركة الزلاقة","معركة الأرك","معركة بلاط الشهداء","معركة وادي لكة"],"correct":2,"source":"الكامل في التاريخ لابن الأثير؛ نفح الطيب للمقري","explanation":"وقعت معركة بلاط الشهداء سنة 114هـ بين بواتييه وتور واستشهد فيها عبد الرحمن الغافقي."},
  {"id":633,"category":"التاريخ","difficulty":"صعب","type":"mcq","question":"في أي معركة كبرى في الأندلس انتصر قائد المرابطين يوسف بن تاشفين سنة 479هـ؟","options":["معركة العقاب","معركة حطين","معركة عين جالوت","معركة الزلّاقة"],"correct":3,"source":"الكامل في التاريخ لابن الأثير؛ البداية والنهاية لابن كثير","explanation":"نصر الله المسلمين بقيادة يوسف بن تاشفين والمعتمد بن عباد في معركة الزلاقة سنة 479هـ."},
  {"id":634,"category":"التاريخ","difficulty":"صعب","type":"mcq","question":"من القائد الذي استعاد إمارة الرها من الصليبيين سنة 539هـ وكان والد نور الدين محمود؟","options":["عماد الدين زنكي","أسد الدين شيركوه","نجم الدين أيوب","الظاهر بيبرس"],"correct":0,"source":"الكامل في التاريخ لابن الأثير؛ البداية والنهاية لابن كثير","explanation":"استردّ عماد الدين زنكي إمارة الرها سنة 539هـ فكان ذلك مفتاح التحرير اللاحق."},
  {"id":635,"category":"العقيدة","difficulty":"سهل","type":"mcq","question":"ما الشهادة التي يدخل بها الإنسان في دين الإسلام وتُعرف بكلمة التوحيد؟","options":["سبحان الله العظيم","لا إله إلا الله محمد رسول الله","الحمد لله رب العالمين","أستغفر الله العظيم"],"correct":1,"source":"صحيح البخاري، حديث 8؛ صحيح مسلم، كتاب الإيمان","explanation":"الشهادتان هما الركن الأول من أركان الإسلام وأساس الدخول في الدين."},
  {"id":636,"category":"العقيدة","difficulty":"سهل","type":"mcq","question":"من النبي الذي اتخذه الله خليلاً ولُقِّب بـ«خليل الرحمن» في القرآن الكريم؟","options":["موسى عليه السلام","نوح عليه السلام","إبراهيم عليه السلام","داود عليه السلام"],"correct":2,"source":"سورة النساء، الآية 125","explanation":"قال تعالى في سورة النساء: «وَاتَّخَذَ اللَّهُ إِبْرَاهِيمَ خَلِيلًا»."},
  {"id":637,"category":"العقيدة","difficulty":"سهل","type":"mcq","question":"من النبي الذي يُلقَّب بـ«كليم الله» لأن الله كلّمه تكليماً؟","options":["عيسى عليه السلام","يوسف عليه السلام","سليمان عليه السلام","موسى عليه السلام"],"correct":3,"source":"سورة النساء، الآية 164","explanation":"قال تعالى: «وَكَلَّمَ اللَّهُ مُوسَىٰ تَكْلِيمًا»."},
  {"id":638,"category":"العقيدة","difficulty":"سهل","type":"mcq","question":"ما الكتاب السماوي الذي آتاه الله نبيّه داود عليه السلام؟","options":["الزبور","التوراة","الإنجيل","القرآن"],"correct":0,"source":"سورة النساء، الآية 163","explanation":"قال تعالى: «وَآتَيْنَا دَاوُودَ زَبُورًا»."},
  {"id":639,"category":"العقيدة","difficulty":"سهل","type":"mcq","question":"ما الكتاب السماوي الذي أنزله الله على نبيّه موسى عليه السلام؟","options":["الزبور","التوراة","الإنجيل","صحف إبراهيم"],"correct":1,"source":"سورة المائدة، الآية 44","explanation":"أنزل الله التوراة على موسى عليه السلام فيها هدى ونور لبني إسرائيل."},
  {"id":640,"category":"العقيدة","difficulty":"سهل","type":"mcq","question":"ما الكتاب السماوي الذي آتاه الله نبيّه عيسى عليه السلام؟","options":["التوراة","الزبور","الإنجيل","الفرقان"],"correct":2,"source":"سورة المائدة، الآية 46","explanation":"أنزل الله الإنجيل على عيسى عليه السلام مصدقاً لما بين يديه من التوراة."},
  {"id":641,"category":"العقيدة","difficulty":"متوسط","type":"mcq","question":"ما اسم الموضع في السماء السابعة الذي انتهى إليه النبي ﷺ ليلة المعراج وعنده جنة المأوى؟","options":["جبل الطور","وادي طوى","المسجد الأقصى","سدرة المنتهى"],"correct":3,"source":"سورة النجم، الآيات 13–15؛ صحيح البخاري، كتاب مناقب الأنصار","explanation":"ورد ذكر سدرة المنتهى في سورة النجم عند نزول جبريل وبلوغ النبي ﷺ إليها في المعراج."},
  {"id":642,"category":"العقيدة","difficulty":"متوسط","type":"mcq","question":"ما المقصود بالإيمان بالبعث بعد الموت؟","options":["إحياء الله للموتى يوم القيامة للحساب والجزاء","تناسخ الأرواح في الدنيا","بقاء الأجساد في القبور بلا حساب","مغادرة الدنيا إلى الأبد دون جزاء"],"correct":0,"source":"سورة يس، الآيات 51–52؛ سورة التغابن، الآية 7","explanation":"البعث إحياء الموتى حين يُنفخ في الصور للقيام لرب العالمين والحساب."},
  {"id":643,"category":"العقيدة","difficulty":"متوسط","type":"mcq","question":"من أفضل الرسل والأنبياء قاطبةً عند أهل السنة والجماعة؟","options":["نوح ثم داود عليهما السلام","محمد ﷺ ثم إبراهيم عليه السلام","يوسف ثم يحيى عليهما السلام","لوط ثم صالح عليهما السلام"],"correct":1,"source":"سورة الأحزاب، الآية 40؛ شرح العقيدة الطحاوية","explanation":"محمد ﷺ سيد ولد آدم وخاتم الأنبياء وأفضلهم، ويليه في الفضل إبراهيم الخليل."},
  {"id":644,"category":"العقيدة","difficulty":"متوسط","type":"mcq","question":"ما معنى اسم الله تعالى «القيُّوم» الوارد في آية الكرسي؟","options":["المختص بالنهار دون الليل","الذي يخلق في وقت دون آخر","القائم بنفسه الغني عن خلقه، والمُقيم لغيره بتدبيره وحفظه","الذي يحتاج إلى أعوان في ملكه"],"correct":2,"source":"تفسير ابن كثير، سورة البقرة الآية 255؛ شرح أسماء الله الحسنى","explanation":"القيوم هو المستغني عن كل ما سواه، والقائم بتدبير السماوات والأرض ومن فيهن."},
  {"id":645,"category":"العقيدة","difficulty":"متوسط","type":"mcq","question":"ما حكم دعاء غير الله من الأموات أو الغائبين في جلب النفع أو دفع الضر الذي لا يقدر عليه إلا الله؟","options":["أمر مستحب للتبرك","مباح إذا حسنت النية","مكروه تنزيهاً فقط","شرك أكبر مخرج من الملة"],"correct":3,"source":"سورة يونس، الآية 106؛ سورة الجن، الآية 18","explanation":"الدعاء عبادة خالصة لله، وصرفه لغير الله فيما لا يقدر عليه إلا الله شرك أكبر."},
  {"id":646,"category":"العقيدة","difficulty":"متوسط","type":"mcq","question":"ما القاعدة الاعتقادية التي يقررها قوله تعالى: «لَيْسَ كَمِثْلِهِ شَيْءٌ ۖ وَهُوَ السَّمِيعُ الْبَصِيرُ»؟","options":["إثبات صفات الله مع تنزيهه عن مماثلة المخلوقين","نفي جميع الأسماء والصفات عن الله","تشبيه صفات الخالق بصفات البشر","إنكار السمع والبصر الإلهيين"],"correct":0,"source":"سورة الشورى، الآية 11؛ العقيدة الواسطية لابن تيمية","explanation":"الآية تجمع بين التنزيه في «ليس كمثله شيء» والإثبات في «وهو السميع البصير»."},
  {"id":647,"category":"العقيدة","difficulty":"صعب","type":"mcq","question":"من الإمام الذي يُنسب إليه متن «العقيدة الطحاوية» المشهور في بيان عقيدة أهل السنة؟","options":["الإمام ابن أبي زيد القيرواني","الإمام أبو جعفر الطحاوي","الإمام أبو الحسن الأشعري","الإمام البربهاري"],"correct":1,"source":"العقيدة الطحاوية لأبي جعفر الطحاوي","explanation":"ألّف الإمام أبو جعفر أحمد بن محمد الطحاوي (ت 321هـ) هذه الرسالة لبيان عقيدة السلف."},
  {"id":648,"category":"العقيدة","difficulty":"صعب","type":"mcq","question":"من مؤلف متن «العقيدة الواسطية»؟","options":["الإمام ابن القيم","الإمام الشاطبي","شيخ الإسلام ابن تيمية","الإمام الغزالي"],"correct":2,"source":"مجموع الفتاوى لابن تيمية؛ العقيدة الواسطية","explanation":"كتب ابن تيمية رحمه الله العقيدة الواسطية بطلب قاضٍ من مدينة واسط العراقية."},
  {"id":649,"category":"العقيدة","difficulty":"صعب","type":"mcq","question":"ما المقصود بـ«عصمة الأنبياء» عند أهل السنة والجماعة؟","options":["عدم تعرضهم للمرض أو الجوع أبداً","عدم موتهم كسائر البشر","معرفتهم بالغيب المطلق من أنفسهم","حفظهم من الكبائر ومن الخطأ في تبليغ الوحي عن الله"],"correct":3,"source":"شرح العقيدة الطحاوية لابن أبي العز؛ لوامع الأنوار البهية","explanation":"الأنبياء معصومون في تبليغ رسالات الله وعن الفواحش والكبائر مع جريان البشرية عليهم."},
  {"id":650,"category":"العقيدة","difficulty":"صعب","type":"mcq","question":"ما «الأعراف» المذكور في سورة الأعراف؟","options":["سور مرتفع بين الجنة والنار يقف عليه قوم تساوت حسناتهم وسيئاتهم","باب من أبواب جهنم","وادٍ في مكة المكرمة","شجرة في أصل الجنة"],"correct":0,"source":"سورة الأعراف، الآيات 46–49؛ تفسير ابن كثير","explanation":"أصحاب الأعراف قوم تساوت حسناتهم وسيئاتهم فيقفون بين الجنة والنار ثم يدخلهم الله الجنة برحمته."},
  {"id":651,"category":"العقيدة","difficulty":"صعب","type":"mcq","question":"ما الفرق بين «التوكل» المشروع و«التواكل» المذموم؟","options":["التوكل ترك الأخذ بالأسباب","التوكل صدق الاعتماد على الله مع الأخذ بالأسباب، والتواكل ترك الأسباب","كلاهما بمعنى واحد في الشرع","التواكل أعلى درجة من التوكل"],"correct":1,"source":"سنن الترمذي، باب اعقلها وتوكل؛ صحيح البخاري، كتاب الرقاق","explanation":"التوكل يجمع بين اعتماد القلب على الله والسعي بالأسباب المشروعة."},
  {"id":652,"category":"العقيدة","difficulty":"صعب","type":"mcq","question":"ما الشرطان اللذان قررهما القرآن الكريم لصحة الشفاعة يوم القيامة؟","options":["المال والجاه في الدنيا","الأنساب دون عمل صالح","إذن الله للشافع ورضاه عن المشفوع له","القوة والسلطان في الأرض"],"correct":2,"source":"سورة النجم، الآية 26؛ سورة الأنبياء، الآية 28","explanation":"لا تنفع شفاعة الشافعين يوم القيامة إلا بعد أن يأذن الله لمن يشاء ويرضى."},
  {"id":653,"category":"العقيدة","difficulty":"صعب","type":"mcq","question":"ما معنى اسم الله تعالى «الصَّمَد» في سورة الإخلاص عند جمهور المفسرين؟","options":["الذي لا يُسأل في الشدائد","الذي يخلق في وقت دون آخر","الذي له ولد وشريك","السيد الكامل الذي تصمد إليه الخلائق في حوائجها وهو الغني عن كل أحد"],"correct":3,"source":"تفسير الطبري وتفسير ابن كثير، سورة الإخلاص، الآية 2","explanation":"الصمد هو السيد الذي كمل في سؤدده وعلمه وقدرته، وتقصده المخلوقات كلها في حاجاتها."},
  {"id":654,"category":"العقيدة","difficulty":"صعب","type":"mcq","question":"ما العلامة الكبرى من علامات الساعة التي إذا وقعت أُغلق باب التوبة ولا ينفع نفساً إيمانها لم تكن آمنت من قبل؟","options":["طلوع الشمس من مغربها","كثرة العمران في الأرض","بناء المساجد المزخرفة","تطاول الناس في البنيان"],"correct":0,"source":"سورة الأنعام، الآية 158؛ صحيح البخاري، حديث 4635","explanation":"إذا طلعت الشمس من مغربها ورآها الناس آمنوا أجمعون، حين لا ينفع نفساً إيمانها لم تكن آمنت من قبل."}
